SELECT d.order_id,d.order_item_id,c.product_id,c.product_category_name_english,v.seller_id,d.price,d.freight_value,d.order_status FROM dw.FactDetallePedido d JOIN dw.DimProducto c ON c.producto_key=d.producto_key JOIN dw.DimVendedor v ON v.vendedor_key=d.vendedor_key WHERE d.order_id=@OrderId AND LEN(@OrderId) BETWEEN 1 AND 64 ORDER BY d.order_item_id;
